export const TASKS={planning:'교육과정·업무 준비',care:'학생 지원 사례 연구',digital:'디지털·발명 자료 준비',expression:'표현·공연 수업 준비',records:'학적·평가 근거 검토',library:'독서·진로 자료 탐색',assessment:'학습 보완 자료 준비'};
export function data(s){return s.schoolReview??={schema:1,assessments:[],preparation:[],credits:[],closures:[],auditEvidence:[],renewals:[],workshops:[],next:1};}
export function prepare(s,area,detail){const d=data(s);if(!TASKS[area]||String(detail).trim().length<8)return {error:'준비 영역과 구체적인 결과물을 적어 주세요.'};const active=C.data(s).activeSkills,skills=s.teacher.skills.filter(sk=>active.includes(sk.name)&&SKILL_EFFECTS[sk.name]?.[0]===area),bonus=Math.min(8,skills.reduce((n,sk)=>n+sk.level,0)),minutes=30-bonus,energy=4+skills.length;if(!W.free(s,minutes)||M.currentSlot(s).kind!=='afternoon'||s.teacher.energy<energy)return {error:'수업 후 겹치지 않는 '+minutes+'분과 여유 '+energy+'가 필요합니다.'};if(d.preparation.some(x=>x.day===s.day&&x.area===area))return {error:'오늘 같은 영역의 준비는 기록되어 있습니다.'};M.advance(s,minutes);s.teacher.energy=M.clamp(s.teacher.energy-energy);const row={day:s.day,area,minutes,energy,skills:skills.map(sk=>sk.name),detail:String(detail).slice(0,1000),date:M.stamp(s)};d.preparation.push(row);M.addNote(s,'teacher',TASKS[area]+': '+row.detail);return {ok:true};}
export function assess(s,subject,kind,minutes,ids,evidence){const d=data(s),slot=M.currentSlot(s);if(!M.subjects(s.config.grade).includes(subject)||!['unit','dictation','makeup','performance'].includes(kind)||![5,10,15,20].includes(minutes)||String(evidence).trim().length<8)return {error:'과목·평가 방법·소요 시간과 확인할 근거를 작성해 주세요.'};if(s.staffWork?.away||M.movementBusy(s)||s.minute+minutes>slot.end||P.conflicts(s,s.day,s.minute,s.minute+minutes).length||!(slot.kind==='lesson'&&slot.subject===subject||slot.kind==='afternoon'))return {error:'해당 과목 수업 또는 수업 후 겹치지 않는 시간에 실시합니다.'};const members=[...new Set(ids)].filter(id=>s.students.some(st=>st.id===id));if(!members.length)return false;const available=new Set(M.remainingStudents(s).filter(st=>Support.available(s,st.id)).map(st=>st.id));const present=members.filter(id=>available.has(id));if(!present.length)return {error:'평가에 참여할 학생이 학교에 없습니다.'};const specialist=s.config.grade>=3&&Object.values(s.academic.schoolPlan.days||{}).flat().some(r=>r.specialist&&r.subject===subject);const row={id:'assessment-'+s.academic.year+'-'+d.next++,day:s.day,subject,kind,minutes,start:s.minute,period:slot.period||null,evidence:String(evidence).slice(0,1000),owner:specialist?'specialist':'teacher',status:'draft',results:members.map(id=>({id,participated:present.includes(id),level:present.includes(id)?'보통':'미실시',evidence:''})),date:M.stamp(s)};M.advance(s,minutes);d.assessments.push(row);return {ok:true,id:row.id};}
export function editAssessment(s,id,values){const a=data(s).assessments.find(x=>x.id===id);if(!a||a.status!=='draft')return {error:'확정 또는 전담 인계 후에는 초안을 바꿀 수 없습니다.'};const patch=a.results.map(r=>{const v=values[r.id];if(!v||!['잘함','보통','보완 필요','미실시'].includes(v.level))return null;if(!r.participated&&v.level!=='미실시')return null;return {...r,level:v.level,evidence:String(v.evidence||'').slice(0,500)};});if(patch.some(r=>!r||r.participated&&r.level!=='미실시'&&r.evidence.trim().length<5))return {error:'참여 학생별 직접 확인한 근거를 적어 주세요. 미참여는 미실시로 유지합니다.'};a.results=patch;return {ok:true};}
export function finalize(s,id){const a=data(s).assessments.find(x=>x.id===id);if(!a||a.status==='final')return false;if(a.results.some(r=>r.participated&&r.level!=='미실시'&&r.evidence.trim().length<5))return {error:'학생별 평가 근거를 먼저 검토해 주세요.'};if(a.owner==='specialist'&&a.status==='draft'){a.status='review';a.sentDay=s.day;a.readyDay=s.academic.calendar.find(d=>d.school&&d.day>s.day)?.day??s.day+1;M.addMessage(s,'grade','나',a.subject+' 평가 관찰 자료를 전담교사에게 인계합니다.',{senderId:'teacher',recipientId:'specialist'});return {ok:true};}if(a.owner==='specialist'&&s.day<a.readyDay)return {error:'다음 등교일 전담교사의 검토 회신을 확인해 주세요.'};for(const r of a.results){const st=s.students.find(x=>x.id===r.id);if(!st)continue;st.records.unshift({day:a.day,date:a.date,kind:a.kind==='performance'?'performance':'unit',kindLabel:a.kind==='makeup'?'보완 평가':a.kind==='dictation'?'받아쓰기':a.kind==='performance'?'수행평가':'단원평가',subject:a.subject,level:r.level,text:r.evidence||'미실시 · 별도 보완 필요',owner:a.owner,assessmentId:a.id,minutes:a.minutes,order:Date.now()});}a.status='final';a.finalized=M.stamp(s);if(a.owner==='specialist')M.addMessage(s,'grade','김지완 전담교사',a.subject+' 관찰 자료와 참여 여부를 대조하여 평가 결과를 확정했습니다.',{senderId:'specialist',plannerScanned:true});return {ok:true};}
export function priorCredits(s,id){const st=s.students.find(x=>x.id===id);if(!st)return [];return (s.career?.archives||[]).filter(a=>a.students.some(x=>x.personKey===st.personKey)).map(a=>({year:a.year,grade:a.grade,school:a.school,hours:a.lessons.reduce((o,r)=>{const ids=r.participantIds||r.present;if(Array.isArray(ids)?ids.includes(a.students.find(x=>x.personKey===st.personKey).id):r.count===a.students.length)o[r.subject]=(o[r.subject]||0)+1;return o;},{}),status:a.lessons.every(r=>Array.isArray(r.participantIds||r.present)||r.count===a.students.length)?'개별 참여 근거 확인':'일부 수업의 개인별 참여 근거 미확인'}));}
export function closure(s,day,reason){
 const d=data(s),row=s.academic.calendar.find(x=>x.day===day);
 if(!row||day<=s.day||!row.school||String(reason).trim().length<8)return {error:'앞으로의 등교일과 학교의 휴업 결정 내용을 입력해 주세요.'};
 if(s.academic.events.some(e=>e.day===day&&!['cancelled','missed'].includes(e.status)))return {error:'해당 날짜의 학교 행사를 먼저 다른 등교일로 조정해 주세요.'};
 const tutor=s.schoolLife.tutoring,affected=tutor?.days?.includes(day),replacement=affected?s.academic.calendar.find(x=>x.school&&x.term===A.info(s,day).term&&x.day>day&&x.day%5===tutor.weekday&&!tutor.days.includes(x.day)&&!P.conflicts(s,x.day,920,960).length):null;
 if(affected&&!replacement)return {error:'학기 안에 같은 요일의 기초학력지도 보완일을 확보할 수 없습니다. 학교와 지도 일정부터 협의해 주세요.'};
 const lessons=structuredClone(A.plannedSchedule(s,day)),cancelled=P.data(s).entries.filter(e=>e.day===day&&e.status==='예정');for(const e of cancelled)e.status='취소';
 if(affected){tutor.days=tutor.days.map(n=>n===day?replacement.day:n).sort((a,b)=>a-b);tutor.changes??=[];tutor.changes.push({from:day,to:replacement.day,reason:'학교 휴업 · 주 1회·학기 10회 유지',date:M.stamp(s)});}
 row.school=false;row.reason=String(reason).slice(0,100);d.closures.push({day,date:M.stamp(s),reason:row.reason,lessons,cancelled:cancelled.map(e=>e.id),tutoringReplacement:replacement?.day??null});s.academic.closures.push({day,reason:row.reason});
 for(const r of s.academic.reservations)if(r.day===day)r.cancelled=true;
 M.addMessage(s,'all','한정우 교감',M.dateLabel({day})+' 휴업 결정: '+row.reason+' · 학급 시수와 보완 계획을 확인해 주세요.'+(replacement?' 기초학력지도는 '+M.dateLabel({day:replacement.day})+' 같은 요일로 보완합니다.':''),{senderId:'principal',plannerScanned:true});return {ok:true};
}
export function undoClosure(s,day){const item=data(s).closures.find(c=>c.day===day&&!c.restored);if(!item||day<=s.day)return false;const row=s.academic.calendar.find(x=>x.day===day);row.school=true;row.reason='';item.restored=M.stamp(s);M.log(s,'학교 휴업 변경 취소 · 기존 약속은 자동 재예약하지 않습니다.');return {ok:true};}
export function auditFindings(s){const items=[];if(!s.classCurriculum?.active)items.push({id:'curriculum',title:'학급교육과정 확정 근거',ok:false});else items.push({id:'curriculum',title:'학급교육과정 확정 근거',ok:true});const inv=s.inventory||{};items.push({id:'budget',title:'물품 주문·예산의 잔액 및 재고',ok:s.budget>=0&&Object.values(inv).every(n=>n>=0)});items.push({id:'attendance',title:'지난 등교일 출결 확인',ok:s.academic.calendar.filter(x=>x.school&&x.day<s.day).every(x=>s.attendanceConfirmed[x.day])});items.push({id:'records',title:'확정 행동특성의 검토 이력',ok:(s.recordReview?.reports||[]).every(r=>!r.locked||r.confirmed&&r.evidence?.length)});items.push({id:'assessments',title:'전담 평가 인계 미결 여부',ok:!data(s).assessments.some(a=>a.status==='review')});items.push({id:'aids',title:'보조도구 반납 점검',ok:!People.data(s).loans.some(l=>l.returned&&l.condition==='점검 필요')});return items;}
export function auditEvidence(s,id,note){if(!W.audit(s).current||!auditFindings(s).some(x=>x.id===id)||String(note).trim().length<8||!W.free(s,10))return {error:'진행 중인 감사의 점검 항목과 실제 증빙 설명, 10분이 필요합니다.'};M.advance(s,10);data(s).auditEvidence.push({id,year:s.academic.year,note:String(note).slice(0,1000),check:structuredClone(auditFindings(s).find(x=>x.id===id)),date:M.stamp(s)});return {ok:true};}
export function renew(s,topic,goal){const p=W.project(s),sc=C.data(s).schools.find(x=>x.id===C.data(s).schoolId);if(s.academic.year<=sc.projectEnd&&!p.shared)return {error:'현재 지정 기간에는 운영 결과 공유 후 재지정을 협의합니다.'};if(!['사회정서','AI·디지털','독서','진로','생태환경','기초학력','예술','학생자치'].includes(topic)||String(goal).trim().length<8||!W.free(s,20))return {error:'선도사업 분야·우리 반 담당 목표와 20분을 확인해 주세요.'};const existing=data(s).renewals.find(r=>r.year===s.academic.year&&r.school===sc.id);if(existing)return {error:'이번 학년도 재지정 협의 기록이 있습니다.'};M.advance(s,20);sc.leading=topic;sc.projectEnd=s.academic.year+2;data(s).renewals.push({school:sc.id,year:s.academic.year,topic,goal:String(goal).slice(0,300),date:M.stamp(s),status:'가상 교육지원청 협의 승인'});W.data(s).projects={topic,year:s.academic.year,selected:true,goal:String(goal).slice(0,300),required:11,shared:false,renewed:true};return {ok:true};}
export function workshop(s,id,mode,text){const b=Library.book(id);if(!b||!['librarian','author','create'].includes(mode)||String(text).trim().length<8||!W.free(s,15))return {error:'책과 협의·창작 내용, 수업 밖 15분을 확인해 주세요.'};const prompts={librarian:'사서교사: 한 장을 함께 읽고, 읽은 근거를 찾기 쉬운 쪽에 표시해 보세요. 참여 방식은 말·그림·글로 열어 두면 좋겠습니다.',author:'가상 작가: 등장인물이 무엇을 바랐는지와 실제로 어떤 선택을 했는지 나누어 보세요. 결말을 바꿀 때도 앞 장면의 단서를 남겨 주세요.',create:'학생 창작: 책에서 찾은 단서를 바탕으로 새로운 장면을 썼습니다. 원래 이야기와 새롭게 만든 부분을 구분해 보관합니다.'};M.advance(s,15);data(s).workshops.push({id:'workshop-'+data(s).next++,bookId:id,mode,text:String(text).slice(0,3000),reply:prompts[mode],date:M.stamp(s)});return {ok:true};}
export function valid(s){
 const d=s.schoolReview;if(d==null)return true;const arr=Array.isArray,txt=v=>typeof v==='string'&&v.length<=4000&&!/[<>]/.test(v),ids=People.knownIds(s);
 return d.schema===1&&arr(d.assessments)&&new Set(d.assessments.map(a=>a.id)).size===d.assessments.length&&d.assessments.every(a=>txt(a.id)&&M.subjects(s.config.grade).includes(a.subject)&&['unit','dictation','makeup','performance'].includes(a.kind)&&['draft','review','final'].includes(a.status)&&Number.isInteger(a.day)&&[5,10,15,20].includes(a.minutes)&&Number.isInteger(a.start)&&a.start>=520&&a.start+a.minutes<=1000&&txt(a.evidence)&&['teacher','specialist'].includes(a.owner)&&(a.owner!=='specialist'||s.config.grade>=3)&&(a.status!=='review'||Number.isInteger(a.readyDay)&&a.readyDay>a.day)&&arr(a.results)&&new Set(a.results.map(r=>r.id)).size===a.results.length&&a.results.every(r=>ids.has(r.id)&&typeof r.participated==='boolean'&&['미실시','잘함','보통','보완 필요'].includes(r.level)&&txt(r.evidence)&&(r.participated||r.level==='미실시')&&(a.status==='draft'||r.level==='미실시'||r.evidence.trim().length>=5)))&&arr(d.preparation)&&d.preparation.every(p=>TASKS[p.area]&&p.minutes>=22&&p.minutes<=30&&p.energy>=4&&p.energy<=8&&txt(p.detail))&&arr(d.credits)&&arr(d.closures)&&d.closures.every(c=>Number.isInteger(c.day)&&txt(c.reason)&&arr(c.lessons)&&arr(c.cancelled))&&arr(d.auditEvidence)&&arr(d.renewals)&&arr(d.workshops)&&d.workshops.every(w=>!!Library.book(w.bookId)&&['librarian','author','create'].includes(w.mode)&&txt(w.text)&&txt(w.reply))&&Number.isInteger(d.next)&&d.next>0;
}
